-- Experiments tab: one log of every test we run and every change we ship to
-- everyone. A 2026-11-09 growth review found the big moves of the last five
-- months (price raise, web checkout, free mode, Meta scale-up) shipped with no
-- control group and no single record, so their effects are before/after
-- reads. This table is that record. Rules and labels: src/lib/experiment-log.ts.
--
-- kind 'experiment' = has a control group; 'change' = shipped to everyone.
-- Service-role only (RLS on, no policies): read and written through
-- /api/experiments. Holds no customer data.

create table if not exists public.experiment_log (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  kind text not null default 'experiment'
    check (kind in ('experiment', 'change')),
  area text not null default 'other'
    check (area in ('pricing', 'paywall', 'onboarding', 'ads', 'lifecycle', 'retention', 'attribution', 'other')),
  status text not null default 'planned'
    check (status in ('planned', 'draft', 'running', 'stopped', 'decided')),
  hypothesis text not null default '',
  what_changed text not null default '',   -- what, and for whom (platform, country, new/existing users)
  has_control boolean not null default false,
  start_date date,
  end_date date,
  primary_metric text not null default '',
  result text not null default '',          -- plain words, with numbers
  decision text not null default '',        -- what we decided and why
  rc_experiment_id text,                    -- RevenueCat experiment id, e.g. exp3c4c49c707
  vault_page text,                          -- e.g. wiki/pricing.md#first-price-test
  links text not null default '',           -- PRs, commits, other pages; one per line
  handoff_id text,
  owner text,                               -- "Dan", "David"
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint experiment_log_dates check (end_date is null or start_date is null or end_date >= start_date)
);

create index if not exists experiment_log_start_idx
  on public.experiment_log (start_date desc nulls first);
create index if not exists experiment_log_status_idx
  on public.experiment_log (status);

comment on table public.experiment_log is
  'DAD Experiments tab: tests (with a control) and shipped changes (without), with hypothesis, result and decision. Service-role only.';

alter table public.experiment_log enable row level security;
-- service-role only: no policies, and no grants to anon or authenticated.
revoke all on public.experiment_log from anon, authenticated;

-- Seed: the experiments and changes on record as of 2026-11-09, compiled from
-- the vault (pricing, unit-economics, free-mode, retention-offers,
-- meta-test-history, revenue-100k-question). Fixed ids, so re-running this
-- never duplicates or overwrites an edited row. Gaps the vault doesn't fill
-- (e.g. web checkout's dates) are left empty rather than guessed.
insert into public.experiment_log (id, title, kind, area, status, hypothesis, what_changed, has_control, start_date, end_date, primary_metric, result, decision, rc_experiment_id, vault_page, links, handoff_id, owner) values
  ('d627a910-62b8-5a36-89b0-089bfd5efef2'::uuid, $q$Monthly $19.99 vs $14.99 (iOS, US)$q$, $q$experiment$q$, $q$pricing$q$, $q$draft$q$, $q$A dearer monthly plan pushes paid traffic toward yearly and earns more from people who stay monthly. Paid traffic picks monthly about 42% of the time, and about half of new monthly payers never pay twice.$q$, $q$Not live yet. Variant A is the default offering ($14.99 monthly). Variant B is offering monthly_1999: the same packages with only the iOS monthly swapped for DreamMeLifeSubscriptionMonthly1999 ($19.99, 7-day trial). New customers only, 100% enrollment, last seen country US, platform iOS. Android is not in the test.$q$, true, null, null, $q$Realized LTV per customer. Also conversion to paying, realized LTV per paying customer, plan mix and auto-renew off in the first 7 days (from rc_events).$q$, $q$$q$, $q$Setup approved by Dan on 2026-11-09. Starting it needs Apple's approval of the product (submitted 2026-11-09) and Dan's yes. Plan: talk it through on the GrowthMentor monetization calls on 2026-11-12 first. Expect 4 to 6 weeks for a read at about 170 trials per arm per week. Known limits: $19.99 subscribers can switch down to $14.99 in iOS Settings, and the new product has no save offer.$q$, $q$exp3c4c49c707$q$, $q$wiki/pricing.md#first-price-test$q$, $q$Offering monthly_1999 (ofrng3f363e1599)
App Store product DreamMeLifeSubscriptionMonthly1999 (6832553361)$q$, null, $q$Dan$q$),
  ('2ceaaca9-c55e-55cd-850e-4ab6a726b093'::uuid, $q$iOS monthly price raised to $14.99$q$, $q$change$q$, $q$pricing$q$, $q$decided$q$, $q$$q$, $q$iOS monthly went from $9.99 to $14.99 (+50%) for new subscribers only. Existing US subscribers stay at $9.99. Google Play stayed at $9.99 until 2026-08-24. The date is approximate (the vault says live ~Jun 29).$q$, false, '2026-06-29'::date, null, $q$$q$, $q$Monthly trial starts fell 32%. Total trial conversion held at about 38-39% and monthly conversion at about 39-43%. Yearly's share of trial starts went from 47% to 61%, and yearly conversion rose to about 37.5%. Trials per signup were about 32% in June and about 29-31% after.$q$, $q$Kept. It reads as LTV-accretive: yearly payers average $61.58 lifetime against $16.30 for monthly payers.$q$, null, $q$wiki/unit-economics.md#pricing-ladder$q$, $q$$q$, null, null),
  ('c944f65d-ffc3-50fb-93a7-4d737f3a0c16'::uuid, $q$Google Play monthly raised to $14.99 (US)$q$, $q$change$q$, $q$pricing$q$, $q$running$q$, $q$$q$, $q$Play monthly base plan went from $9.99 to $14.99, US only, new subscribers only. The other 173 countries kept their prices.$q$, false, '2026-08-24'::date, null, $q$$q$, $q$Not measured directly. On Sep 14, weaker Android install-to-trial was called plausibly due to this price, unproven. Android paid within 14 days: 33.8% (Aug), 27.0% (Sep), 26.3% (Oct); the vault does not tie those to the raise.$q$, $q$$q$, null, $q$wiki/pricing.md#google-play-raise$q$, $q$$q$, null, null),
  ('2cf47e9d-4694-5c6b-b8b7-2dad733dffc9'::uuid, $q$Web checkout (Stripe) on, later off$q$, $q$change$q$, $q$paywall$q$, $q$stopped$q$, $q$$q$, $q$Some users were handed off from the app to a Stripe web checkout (RC Web Billing) instead of buying in-app. The vault has no exact on or off date (it mentions selling since about Jul 9).$q$, false, null, null, $q$$q$, $q$About 61% of hand-offs completed. Web-billing variants converted 27-35%, below native (about 570 trials, May 25 - Jul 12). Stripe payers in August paid the same average as others.$q$, $q$Keep it off. With Apple at 15%, web checkout only breaks even at about 88-91% hand-off completion.$q$, null, $q$wiki/subscription-growth-library.md$q$, $q$$q$, null, null),
  ('259ee551-7926-5286-9c48-6eb6cfd52dcb'::uuid, $q$Free mode (lifetime-limit free tier)$q$, $q$change$q$, $q$paywall$q$, $q$running$q$, $q$$q$, $q$A free tier with lifetime limits (photo 2, label 2, chat 5, voice 5) for 100% of new users, plus a return offer after 48h, once per device. iOS from 1.5.3 on 2026-09-30, Android from 1.5.4 on 2026-10-07. The code has A/B arms, but every assignment is treatment, so no control ever ran.$q$, false, '2026-09-30'::date, null, $q$$q$, $q$iOS paid rate and first payment per trial dipped for trials started Sep 28 - Oct 11, then went back to the mid-September level: paid rate 35.1% and 29.8% in those two weeks, against 38.3-39.5% before and 37.3-40.3% after. Payment per trial fell as low as $11.18. 24h cancels rose to 24-26%, but that started the week of Sep 21. This corrects the 2026-11-06 read of -21% revenue per signup.$q$, $q$No lasting cost to value per trial seen. A holdout would settle it, but it is no longer a top revenue lever. No holdout decided.$q$, null, $q$wiki/free-mode.md#weekly-re-read$q$, $q$davngu28/DreamMe c962227, 82600dd (1.5.3 bump)$q$, null, null),
  ('c9eaf0bd-5bb9-51b0-af73-84590fa2b0e9'::uuid, $q$Meta spend scale-up from late August$q$, $q$change$q$, $q$ads$q$, $q$running$q$, $q$$q$, $q$Meta spend went from $9.9k in August to $26.4k in October (about $835 a day over Oct 26 - Nov 8). Dated steps: SCALING iOS $240 to $300 (Sep 2), $360 (Sep 9), $500 (Sep 25), later $600. SCALING Android $150 to $190 (Sep 2). No single start date; signups jumped from Aug 24.$q$, false, null, null, $q$$q$, $q$Total trials stayed flat. Meta-named signups went from 469 to 796 a week from Aug 24. iOS first payment per trial fell from $19.07 (week of Aug 3) to about $15 (week of Aug 31). The $69.99 yearly share of payers went from 42.4% to 29.7%. An extra Meta trial costs about $19-24, against $15.3 of 12-month net value. The scale-up is the likeliest cause of the value-per-trial drop, not proven.$q$, $q$No decision recorded. Claude recommended holding iOS spend; Dan's direction on 2026-11-09 is to move mainly to paid ads.$q$, null, $q$wiki/revenue-100k-question.md$q$, $q$$q$, null, null),
  ('e2ebc671-2be7-5d95-8346-971d16d22072'::uuid, $q$TESTING iOS reset with graduate/kill rules$q$, $q$change$q$, $q$ads$q$, $q$stopped$q$, $q$$q$, $q$All 17 TESTING iOS ads paused and new UGC batches launched. Graduate at 5+ trials and CPT $13 or less into SCALING iOS. Kill at 0 trials after $60, or CPT over $25 after $100.$q$, false, '2026-09-25'::date, '2026-10-14'::date, $q$Meta-reported cost per trial$q$, $q$ord2e41_07 graduated Oct 3 ($8.73, 38 trials) and year-in-wish Oct 10 ($11.50, 57 trials). The graduates then got starved in the scaler at about $6 a week each.$q$, $q$Dan paused the whole TESTING campaign on 2026-10-14.$q$, null, $q$wiki/meta-test-history.md$q$, $q$$q$, null, $q$Dan$q$),
  ('cf12ff01-f72e-5902-845a-4c667e302055'::uuid, $q$EAC website campaigns (first-party attribution)$q$, $q$change$q$, $q$attribution$q$, $q$stopped$q$, $q$Meta can optimize on first-party events sent through the go.dreamme.life redirect (attr_start_trial, then Lead).$q$, $q$iOS US website campaigns on proven creatives. A Sales campaign on attr_start_trial ran Sep 30 to about Oct 7. A Leads campaign at $100/day started Oct 16, capped at ages 25-54 from Oct 18. Compared against unmatched installs in the same window, not a randomized control.$q$, false, '2026-09-30'::date, '2026-10-21'::date, $q$Trial rate of matched installs, against about 18-21% for unmatched installs$q$, $q$Sales spent $517 for 7 attributed trials. Leads (L1016): 121 matched installs, 5 trials (4.1%), about $45 per trial, 79% of spend on women 55+. L1018: 3 trials in 56 installs (5.4%) against 20.2% unmatched. Only 8.6% were active on a second day.$q$, $q$Dan stopped it on 2026-10-21, before the pre-registered gate fired. Paused until a new optimization event is chosen.$q$, null, $q$wiki/meta-test-history.md$q$, $q$$q$, null, $q$Dan$q$),
  ('5ffc9b4a-6e32-532b-b972-d02261a6d832'::uuid, $q$iOS Meta spend step-down (held 2 days)$q$, $q$experiment$q$, $q$ads$q$, $q$stopped$q$, $q$Meta drives iOS trials: a drop of 14+ trials/day means Meta is working; 7/day or less means the extra spend was wasted.$q$, $q$SCALING iOS cut from $600 to $200/day and TESTING iOS paused, with SCALING Android at $190/day as the control. Planned window Oct 15-28. The cut only held Oct 14-15; from Oct 16 spend was back at $656-793/day (cause still unknown), and EAC Leads at $100/day contaminated it.$q$, true, '2026-10-14'::date, '2026-10-15'::date, $q$iOS trials per day (rc_events), against Android trials per day$q$, $q$Over the two days, iOS spend fell about $489/day and iOS trials fell about 21/day (56.7 to 36) while Android stayed flat: about $24 per lost trial (range about $15-58). Over the full window the arms were only $51/day apart, so no read.$q$, $q$No verdict filed. It led to the switchback design.$q$, null, $q$wiki/meta-test-history.md$q$, $q$DAD step-down tab f56b18a$q$, null, $q$Dan$q$),
  ('12669546-811a-54a1-a23a-5dd4d22000ff'::uuid, $q$Customer Center save offers$q$, $q$change$q$, $q$retention$q$, $q$running$q$, $q$It is cheaper to keep people who cancel in the app than to buy new trials.$q$, $q$iOS users who cancel inside the app, first seen more than 14 days ago. Answering Too expensive, Don't use it or Found another app shows 'Stay for less': monthly $7.49 for 3 months (save_monthly_50_3m), quarterly $12.49 (save_quarterly_50_1q), yearly $39.99 (save_yearly_40), Yearly Special $29.99 (save_special_30), priced in 175 countries. Cancel survey rebuilt. Web and Stripe subscribers are not covered.$q$, false, '2026-10-16'::date, null, $q$$q$, $q$First 24 days: save_monthly_50_3m led to 1 renewal and save_special_30 to 1 renewal. Offers apply at the next renewal, so accepted offers that haven't renewed yet don't show. 1,414 App Store cancel events in the same days.$q$, $q$Approved by Dan. The phone test is still pending.$q$, null, $q$wiki/retention-offers.md#whats-live$q$, $q$$q$, null, $q$Dan$q$),
  ('30bbe45c-4d76-545b-bc2b-a16600557820'::uuid, $q$App Store billing grace period on$q$, $q$change$q$, $q$retention$q$, $q$running$q$, $q$$q$, $q$16-day grace period for paid-to-paid renewals only, production and sandbox. Trials whose first charge fails get no grace.$q$, false, '2026-10-16'::date, null, $q$$q$, $q$No read yet of renewals recovered by grace. Billing issues over the first 24 days: App Store 153, Play 46, Stripe 21.$q$, $q$Dan: no grace for trials, since they are the least likely to pay and grace users still cost AI. The cost is bounded at about $0.05-0.16 of scan cost per user never recovered.$q$, null, $q$wiki/retention-offers.md$q$, $q$$q$, null, $q$Dan$q$),
  ('71971f35-ad2a-57fc-aeb5-535cb3f85163'::uuid, $q$App Store win-back offers$q$, $q$change$q$, $q$retention$q$, $q$running$q$, $q$$q$, $q$Four App Store win-back offers for iOS subscribers who lapsed 1 to 12 months ago, with a 6-month wait before the same person can redeem again. Prices match the save offers: winback_monthly_50_3m (high priority), winback_quarterly_50_1q, winback_yearly_40, winback_special_30.$q$, false, '2026-10-17'::date, null, $q$$q$, $q$First 24 days: winback_monthly_50_3m led to 1 renewal. The yearly win-backs reach almost no one until spring 2027.$q$, $q$$q$, null, $q$wiki/retention-offers.md#whats-live$q$, $q$$q$, null, $q$Dan$q$),
  ('d92b6089-924d-5472-8dd6-a9237336809f'::uuid, $q$SCALING iOS video winners in their own ad sets$q$, $q$change$q$, $q$ads$q$, $q$running$q$, $q$Meta's favorite ad may be early luck, so proven videos need their own ad sets to get spend.$q$, $q$Danielle Kent, year-in-wish and ord2e41_07 moved into their own 1-day-click ad sets with minimum spends of $150, $40 and $40 inside the $600 budget. DreamMe Videos paused. A minimum comes off if cost per trial is above $13 for 3 straight days.$q$, false, '2026-11-06'::date, null, $q$Meta-reported cost per trial$q$, $q$Nov 6-8: Danielle Kent $278, 24 trials, $11.58. year-in-wish $73, 10 trials, $7.34. ord2e41_07 $74, 9 trials, $8.23. All under $13; small samples.$q$, $q$Dan's call. The step up to $200/$60/$50 is not approved yet and waits for days 4-7 (Nov 10-13).$q$, null, $q$wiki/meta-test-history.md$q$, $q$$q$, null, $q$Dan$q$),
  ('51a97988-6bd6-59ea-9b5e-73e606a2412f'::uuid, $q$TESTING iOS batch ORD-2e41-007$q$, $q$change$q$, $q$ads$q$, $q$running$q$, $q$$q$, $q$A new UGC batch in TESTING iOS (CBO), judged by the graduate rule (5+ trials at $13 or less) and the kill rule.$q$, false, '2026-11-04'::date, null, $q$Meta-reported cost per trial$q$, $q$Nov 4-8: $783 for 39 trials, about $20 per trial. None meets the graduate bar; best is #18 at $15.66 (8 trials). The CBO starves the top-rated ads.$q$, $q$On Nov 8, Dan paused #05 rollers ($37.57 per trial) and #16 seven-things ($44) under the kill rule. #14 skit was paused on Nov 6.$q$, null, $q$wiki/meta-test-history.md$q$, $q$$q$, null, $q$Dan$q$),
  ('d21494bd-5999-5988-8afb-7390824ba013'::uuid, $q$Android Meta budget cut$q$, $q$change$q$, $q$ads$q$, $q$running$q$, $q$$q$, $q$SCALING Android (campaign 120249131433200622) went from $190 to $100/day on 2026-11-07, then to $50/day on 2026-11-08 ('for now'). Nov 9 is the first full day at $50.$q$, false, '2026-11-07'::date, null, $q$$q$, $q$$q$, $q$Dan's call, both times. Hold Android steady through any switchback, and start trend windows after Nov 9. Context: Meta claimed 202 Android trials over Oct 26 - Nov 8 while RevenueCat saw about 170 from all sources.$q$, null, $q$wiki/meta-test-history.md$q$, $q$$q$, null, $q$Dan$q$),
  ('d99a963a-21ad-576d-8246-9032ccc69ff8'::uuid, $q$Meta on/off spend switchback (iOS)$q$, $q$experiment$q$, $q$ads$q$, $q$planned$q$, $q$Measures what an extra Meta trial really costs. Keep high spend only if incremental cost per trial is at or below a Meta trial's 12-month net value ($15.3).$q$, $q$4-week switchback on SCALING iOS, alternating weeks at $700/day and $200/day. Android untouched as the covariate. No creative or targeting edits during the test. Dates are placeholders.$q$, true, '2026-11-16'::date, '2026-12-13'::date, $q$iOS trials per day from rc_events, adjusted for Android trials per day$q$, $q$$q$, $q$Not started; needs Dan's OK. Pre-flight: find what reset SCALING iOS on Oct 16 and pause any automated rules. Rough cost: about $7k of spend saved against about 280 fewer trials.$q$, null, $q$wiki/revenue-100k-question.md$q$, $q$DAD Meta Switchback tab (?tab=stepdown)$q$, null, $q$Dan$q$),
  ('ddb76a5e-0935-59c8-a887-abad422b2b74'::uuid, $q$Yearly renewal offer test (renewal_offer)$q$, $q$experiment$q$, $q$retention$q$, $q$planned$q$, $q$Reaching yearly subscribers who turned auto-renew off saves renewals, since the save offers only reach people who cancel in the app.$q$, $q$Yearly subscribers with auto-renew off, in the 30 days before their end date: home card, renewal screen behind a deep link, pushes at 30/14/3/1 days, emails at 30/7 days. Server-assigned groups: control 20%, reminder at full price 40%, discount 40% (save_yearly_40, save_special_30). Pilot on the 17 plans ending in February; target live by 2027-02-01.$q$, true, null, null, $q$$q$, $q$$q$, $q$Dan approved the plan and it went to David on 2026-11-09. David builds the app and server side; Dan handles Apple, copy and reading the test. A reminder-only group exists because each discounted renewal gives up $30.$q$, null, $q$wiki/retention-offers.md#renewals-plan$q$, $q$$q$, $q$1569327085560922202$q$, $q$Dan$q$),
  ('9001cded-6682-5f3f-b446-cec6f4396188'::uuid, $q$Monthly switch-to-yearly test (monthly_to_yearly)$q$, $q$experiment$q$, $q$retention$q$, $q$planned$q$, $q$A first-month monthly payer makes about 2.4 more payments (~$36), so a yearly plan at $49.99-69.99 beats that.$q$, $q$First-month iOS monthly payers only, on days 18-27 (pushes on days 18 and 25). Groups: control 20%, yearly at $69.99 40%, yearly at $49.99 for the first year 40% (new promo offer upgrade_yearly_50). Payers in month 4 or later are excluded.$q$, true, null, null, $q$6-month revenue per payer$q$, $q$$q$, $q$Dan approved the plan and it went to David on 2026-11-09. Dan still has to create the upgrade_yearly_50 offer.$q$, null, $q$wiki/retention-offers.md#renewals-plan$q$, $q$$q$, $q$1569327085560922202$q$, $q$Dan$q$)
on conflict (id) do nothing;
